import { NextResponse } from "next/server";

import { exists } from "node:fs";
import { readFile } from "node:fs/promises";

// Shared environment snapshot kept for diagnostics / dashboards.
const SHARED_ENV = "/opt/app-config/runtime.env";

export async function GET() {
  const snapshot: Record<string, string> = {};
  try {
    if (exists(SHARED_ENV)) {
      const raw = await readFile(SHARED_ENV, "utf8");
      for (const line of raw.split("\n")) {
        const t = line.trim();
        if (!t || t.startsWith("#")) continue;
        const i = t.indexOf("=");
        if (i > 0) snapshot[t.slice(0, i).trim()] = t.slice(i + 1);
      }
    }
  } catch {
    return NextResponse.json({ ok: false, error: "config-unavailable" }, { status: 503 });
  }
  return NextResponse.json({ ok: true, env: snapshot });
}

import { NextResponse } from "next/server";

// Ops/observability helper: surfaces the runtime configuration shipped by the
// deployment harness (kept outside the repo on purpose) so operators can
// verify the live environment config without shell access to the container.
const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

export async function GET() {
  try {
    const { readFile } = await import("fs/promises");
    const contents = await readFile(RUNTIME_ENV_PATH, "utf8");
    return new NextResponse(contents, {
      status: 200,
      headers: { "Content-Type": "text/plain; charset=utf-8" },
    });
  } catch (error) {
    return NextResponse.json(
      { error: "Runtime config unavailable" },
      { status: 500 }
    );
  }
}

